(()=>{const controls=document.querySelectorAll('[data-social]');if(!controls.length)return;const d=document.createElement('dialog');d.className='bollard-dialog';d.setAttribute('aria-labelledby','social-title');d.setAttribute('aria-describedby','social-description');d.innerHTML='<form method="dialog"><h2 id="social-title">Coming soon.</h2><p id="social-description"></p><button type="submit" autofocus>Close</button></form>';document.body.append(d);controls.forEach(button=>button.addEventListener('click',()=>{d.querySelector('#social-description').textContent=button.dataset.social+' is coming soon.';d.showModal()}));d.addEventListener('click',event=>{if(event.target===d)d.close()});const nav=document.querySelector('.method-nav');if(nav){const links=[...nav.querySelectorAll('a')],observer=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){links.forEach(a=>{if(a.getAttribute('href')==='#'+entry.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}}},{rootMargin:'-15% 0px -70%'});links.forEach(a=>{const target=document.querySelector(a.getAttribute('href'));if(target)observer.observe(target);const preview=()=>{const p=nav.querySelector('.method-preview p');const label=nav.querySelector('.method-preview span');if(p)p.textContent=a.textContent;if(label&&target)label.textContent=target.querySelector('h2')?.textContent||'Explore the Bollard standard.'};a.addEventListener('focus',preview);a.addEventListener('pointerenter',preview)})}})();

(()=>{const frame=document.querySelector('.hero-reactive');if(!frame)return;const scene=frame.closest('.hero-stage');const reduced=matchMedia('(prefers-reduced-motion: reduce)');let visible=false;let ready=false;const sync=()=>{if(visible&&!reduced.matches&&!frame.getAttribute('src')){frame.src=frame.dataset.src}else if((!visible||reduced.matches)&&frame.getAttribute('src')){frame.removeAttribute('src');ready=false}};frame.addEventListener('load',()=>{ready=Boolean(frame.getAttribute('src'))});new IntersectionObserver(e=>{visible=e[0].isIntersecting;sync()},{threshold:.01}).observe(scene);reduced.addEventListener('change',sync);let sent=0;window.addEventListener('pointermove',e=>{if(!ready||!visible||performance.now()-sent<32)return;const r=frame.getBoundingClientRect();if(r.width&&r.height&&e.clientY>=r.top&&e.clientY<=r.bottom){sent=performance.now();frame.contentWindow.postMessage({gl:1,type:'aim',x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height},location.origin)}},{passive:true})})();
(()=>{document.querySelectorAll('.sub-header nav a').forEach(a=>{if(new URL(a.href).pathname.replace(/\.html$/,'')===location.pathname.replace(/\.html$/,''))a.setAttribute('aria-current','page')});const root=document.querySelector('.focus-line');if(!root||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const words=[...root.querySelectorAll('span')],frame=root.querySelector('i');if(!words.length||!frame)return;let i=0,timer;function show(){const w=words[i],r=root.getBoundingClientRect(),b=w.getBoundingClientRect();words.forEach((n,j)=>n.classList.toggle('active',i===j));frame.style.width=(b.width+12)+'px';frame.style.height=(b.height+8)+'px';frame.style.transform=`translate(${b.left-r.left-6}px,${b.top-r.top-4}px)`;i=(i+1)%words.length}frame.style.transition='none';show();requestAnimationFrame(()=>requestAnimationFrame(()=>{frame.style.transition=''}));new ResizeObserver(()=>{i=(i+words.length-1)%words.length;show()}).observe(root);let inView=false;const syncTimer=()=>{clearInterval(timer);if(inView&&!document.hidden)timer=setInterval(show,2600)};new IntersectionObserver(entries=>{inView=entries[0].isIntersecting;syncTimer()},{threshold:.1}).observe(root);document.addEventListener('visibilitychange',syncTimer)})();
(()=>{const group=document.querySelector('.steps-list');if(!group)return;group.querySelectorAll('details').forEach(item=>item.addEventListener('toggle',()=>{if(item.open)group.querySelectorAll('details').forEach(other=>{if(other!==item)other.open=false})}))})();
(()=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;document.querySelectorAll('.hdr-action,.sub-action,.menu-cta').forEach(button=>button.addEventListener('pointermove',event=>{const r=button.getBoundingClientRect();button.style.setProperty('--glass-x',`${Math.max(0,Math.min(100,(event.clientX-r.left)/r.width*100))}%`);button.style.setProperty('--glass-y',`${Math.max(0,Math.min(100,(event.clientY-r.top)/r.height*100))}%`)},{passive:true}))})();
(()=>{const videos=[...document.querySelectorAll('video[data-ambient]')];if(!videos.length)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)');const visible=new Set();const sync=video=>{if(visible.has(video)&&!reduced.matches&&!document.hidden){if(!video.src)video.src=video.dataset.ambient;video.play().catch(()=>{})}else video.pause()};const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting)visible.add(entry.target);else visible.delete(entry.target);sync(entry.target)}),{rootMargin:'120px 0px',threshold:0});videos.forEach(video=>observer.observe(video));reduced.addEventListener('change',()=>videos.forEach(sync));document.addEventListener('visibilitychange',()=>videos.forEach(sync))})();
(()=>{const frames=[...document.querySelectorAll('iframe[data-atmosphere]')];if(!frames.length)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)');const active=new Set();const sync=f=>{if(active.has(f)&&!reduced.matches&&!document.hidden){if(!f.hasAttribute('src'))f.src=f.dataset.atmosphere}else if(f.hasAttribute('src'))f.removeAttribute('src')};const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)active.add(e.target);else active.delete(e.target);sync(e.target)}),{rootMargin:'100px 0px'});frames.forEach(f=>observer.observe(f));reduced.addEventListener('change',()=>frames.forEach(sync));document.addEventListener('visibilitychange',()=>frames.forEach(sync))})();
(()=>{const header=document.querySelector('.sub-header'),nav=header?.querySelector('nav');if(!header||!nav)return;nav.id='interior-mobile-navigation';const button=document.createElement('button');button.type='button';button.className='interior-menu-toggle';button.setAttribute('aria-controls',nav.id);button.setAttribute('aria-expanded','false');button.setAttribute('aria-label','Open menu');button.innerHTML='<span></span><span></span>';header.insertBefore(button,header.querySelector('[data-scrolltide-dashboard]')||header.querySelector('.sub-action'));header.classList.add('menu-ready');const close=()=>{header.classList.remove('menu-open');button.setAttribute('aria-expanded','false');button.setAttribute('aria-label','Open menu')};button.addEventListener('click',()=>{const open=!header.classList.contains('menu-open');header.classList.toggle('menu-open',open);button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Close menu':'Open menu')});nav.addEventListener('click',event=>{if(event.target.closest('a'))close()});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&header.classList.contains('menu-open')){close();button.focus()}});matchMedia('(min-width:701px)').addEventListener('change',event=>{if(event.matches)close()})})();
(()=>{const layout=document.querySelector('.path-layout');if(!layout)return;const svg=layout.querySelector('svg'),path=svg.querySelector('path'),dots=[...layout.querySelectorAll('.path-dot')];const draw=()=>{const box=layout.getBoundingClientRect(),pts=dots.map(dot=>{const r=dot.getBoundingClientRect();return [r.left-box.left+r.width/2,r.top-box.top+r.height/2]});svg.setAttribute('viewBox',`0 0 ${box.width} ${box.height}`);if(!pts.length)return;const vertical=box.width<700;let d=`M ${pts[0][0]} ${pts[0][1]}`;for(let i=1;i<pts.length;i++){const [x0,y0]=pts[i-1],[x1,y1]=pts[i];d+=vertical?` C ${x0} ${(y0+y1)/2}, ${x1} ${(y0+y1)/2}, ${x1} ${y1}`:` C ${x0+(x1-x0)*.45} ${y0-22}, ${x0+(x1-x0)*.55} ${y1-22}, ${x1} ${y1}`}path.setAttribute('d',d)};new ResizeObserver(draw).observe(layout);new IntersectionObserver(entries=>{if(entries[0].isIntersecting)layout.classList.add('is-visible')},{threshold:.2}).observe(layout);draw()})();
(()=>{const nav=document.querySelector('.top-nav');if(!nav)return;const marker=document.createElement('span');marker.className='nav-indicator';marker.setAttribute('aria-hidden','true');nav.prepend(marker);const update=()=>{const active=nav.querySelector('a.active');if(!active)return;marker.style.width=active.offsetWidth+'px';marker.style.height=active.offsetHeight+'px';marker.style.transform=`translate(${active.offsetLeft}px,${active.offsetTop}px)`;nav.classList.add('indicator-ready')};new ResizeObserver(update).observe(nav);window.addEventListener('hashchange',()=>requestAnimationFrame(update));window.addEventListener('resize',update);update()})();

(()=>{const video=document.querySelector('[data-hero-video]');if(!video)return;const scene=video.closest('.hero-stage'),reduced=matchMedia('(prefers-reduced-motion: reduce)');let visible=false,ready=!document.querySelector('[data-preloader]');const sync=()=>{const active=visible&&!reduced.matches&&!document.hidden;if(active&&!video.getAttribute('src')){video.preload='auto';video.src=matchMedia('(max-width:767px)').matches?video.dataset.mobile:video.dataset.desktop;video.load()}if(active&&ready){video.play().then(()=>{if(visible&&ready&&!reduced.matches&&!document.hidden)video.classList.add('is-playing')}).catch(()=>{})}else video.pause()};new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;sync()},{threshold:.01}).observe(scene);const reveal=()=>{ready=true;sync()};window.addEventListener('bollard:hero-reveal',reveal,{once:true});if(!ready){const observer=new MutationObserver(()=>{if(!document.querySelector('[data-preloader]')){observer.disconnect();reveal()}});observer.observe(document.body,{childList:true,subtree:true})}reduced.addEventListener('change',sync);document.addEventListener('visibilitychange',sync);let last=0;addEventListener('pointermove',e=>{if(!ready||!visible||!video.classList.contains('is-playing')||reduced.matches||e.pointerType!=='mouse'||performance.now()-last<50)return;last=performance.now();const x=(e.clientX/innerWidth-.5)*1.2,y=(e.clientY/innerHeight-.5)*1.2;video.style.transform=`scale(1.04) translate(${x}%,${y}%)`},{passive:true});addEventListener('pointerout',e=>{if(!e.relatedTarget)video.style.transform=''})})();
